export function parseCsv(text) {
  const rows = [];
  if (!text) return rows;

  let row = [];
  let field = '';
  let rowStarted = false;
  let inQuotes = false;
  let i = 0;

  while (i < text.length) {
    const ch = text[i];

    if (inQuotes) {
      if (ch === '"') {
        if (text[i + 1] === '"') {
          field += '"';
          i += 2;
        } else {
          inQuotes = false;
          i += 1;
        }
      } else {
        field += ch;
        i += 1;
      }
      continue;
    }

    if (ch === '"' && field === '') {
      inQuotes = true;
      rowStarted = true;
      i += 1;
    } else if (ch === ',') {
      row.push(field);
      field = '';
      rowStarted = true;
      i += 1;
    } else if (ch === '\r' && text[i + 1] === '\n') {
      row.push(field);
      rows.push(row);
      row = [];
      field = '';
      rowStarted = false;
      i += 2;
    } else if (ch === '\n') {
      row.push(field);
      rows.push(row);
      row = [];
      field = '';
      rowStarted = false;
      i += 1;
    } else {
      field += ch;
      rowStarted = true;
      i += 1;
    }
  }

  if (rowStarted || row.length > 0) {
    row.push(field);
    rows.push(row);
  }

  return rows;
}

export function toObjects(rows) {
  if (!rows || rows.length === 0) return [];

  const header = rows[0];
  const objects = [];

  for (let r = 1; r < rows.length; r += 1) {
    const row = rows[r];
    const object = {};

    for (let c = 0; c < header.length; c += 1) {
      object[header[c]] = c < row.length ? row[c] : '';
    }

    objects.push(object);
  }

  return objects;
}
